function parseRetryAfter(headerValue, nowMs) {
  if ((typeof headerValue !== 'string' && headerValue !== null && headerValue !== undefined) || typeof nowMs !== 'number' || !Number.isFinite(nowMs)) return null;
  if (headerValue == null) return null;
  const value = headerValue.trim();
  if (/^[0-9]+$/.test(value)) {
    const seconds = BigInt(value);
    return seconds <= 2147483647n ? Number(seconds) : null;
  }
  const imf = /^[A-Z][a-z]{2}, [0-9]{2} [A-Z][a-z]{2} [0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2} GMT$/;
  if (!imf.test(value)) return null;
  const target = Date.parse(value);
  if (!Number.isFinite(target) || new Date(target).toUTCString() !== value) return null;
  const delta = target - nowMs;
  if (delta <= 0) return 0;
  const seconds = Math.ceil(delta / 1000);
  return seconds <= 2147483647 ? seconds : null;
}

